// CHECK JOB – stop with a clear message if the job_id is not in the Job Tracker.
const asked = $("When Called by Agent").first().json.job_id;
const row = $input.all().map((i) => i.json).find((r) => r.job_id);
if (!row) throw new Error("No job found with job_id " + asked + ". Use Find Jobs first to get the right job_id.");
return [{ json: row }];

// BUILD TAILORED CV & COVER LETTER (same safety checks as the main agent)
// - every "top skill" must appear in the real CV, otherwise it is removed
// - any email the AI writes is removed; real contact details are added by code
// - if the AI call failed, stop: nothing is overwritten in the Job Tracker
const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9+#%.]+/g, " ").trim();
const CVN = norm($("Build Tailoring Request").first().json.groqBody.messages[1].content.split("CANDIDATE CV:")[1]);
const SIGN_OFF = "\n\nKind regards,\nYour Name\you@example.com | linkedin.com/in/your-profile | github.com/your-username";
const res = $input.first().json;
let t;
try { t = JSON.parse(res.choices[0].message.content); }
catch (e) { throw new Error("Tailoring failed (Groq): " + String(res.error?.message || e.message).slice(0, 200) + ". Try again in a minute."); }
const skills = (t.top_skills || []).filter((s) => CVN.includes(norm(s)));
const dropped = (t.top_skills || []).filter((s) => !CVN.includes(norm(s)));
const tailored = [
  "PROFESSIONAL SUMMARY (tailored)", t.tailored_summary, "",
  "KEY SKILLS (put these first)", skills.join(" · "), "",
  "PROJECT BULLETS TO USE", ...(t.highlight_bullets || []).map((b) => "- " + b), "",
  "ATS KEYWORDS YOU GENUINELY MATCH: " + (t.ats_keywords_matched || []).join(", "),
  "IN THE AD BUT NOT IN YOUR CV (do NOT add unless true): " + (t.ats_keywords_missing || []).join(", "),
  dropped.length ? "Removed by safety check (not in your CV): " + dropped.join(", ") : ""
].join("\n").trim();
const letter = String(t.cover_letter || "").replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, "").trim() + SIGN_OFF;
return [{ json: { job_id: $("Check Job").first().json.job_id, tailored_cv: tailored, cover_letter: letter,
  matched: t.ats_keywords_matched || [], missing: t.ats_keywords_missing || [], dropped } }];

// SHORT REPLY FOR THE CHAT AGENT – links, not the whole CV, to save tokens.
const job = $("Check Job").first().json;
const t = $("Build Tailored CV").first().json;
const base = "http://localhost:5678/webhook/";
const id = encodeURIComponent(job.job_id);
return [{ json: {
  done: true,
  job: job.title + " at " + job.company,
  used_full_advert: $("Build Tailoring Request").first().json.full_advert,
  cv_page: base + "job-cv?job_id=" + id,
  word_download: base + "tailored-cv?job_id=" + id,
  keywords_matched: t.matched.slice(0, 10),
  in_advert_but_not_in_cv: t.missing.slice(0, 10),
  removed_by_safety_check: t.dropped,
  note: "Saved to the Job Tracker. The cover letter is on the CV page."
} }];
